#include <stdio.h>
int main(void){int n,bt[100],pr[100],rem[100],p[100],tat[100]={0},i,t=0,done=0,chosen;float aw=0,at=0;printf("Number of processes: ");scanf("%d",&n);if(n<1||n>100)return 1;for(i=0;i<n;i++){printf("Burst and priority P%d (higher number = higher priority): ",i+1);scanf("%d%d",&bt[i],&pr[i]);rem[i]=bt[i];p[i]=i+1;}while(done<n){chosen=-1;for(i=0;i<n;i++)if(rem[i]>0&&(chosen==-1||pr[i]>pr[chosen]))chosen=i;if(chosen==-1)break;rem[chosen]--;t++;if(rem[chosen]==0){done++;tat[chosen]=t;}}printf("PID\tBT\tPR\tWT\tTAT\n");for(i=0;i<n;i++){int turnaround=tat[i];int wait=turnaround-bt[i];aw+=wait;at+=turnaround;printf("P%d\t%d\t%d\t%d\t%d\n",p[i],bt[i],pr[i],wait,turnaround);}printf("Avg WT=%.2f Avg TAT=%.2f\n",aw/n,at/n);}